#ifndef SCAMPTRIE_BASE_H
#define SCAMPTRIE_BASE_H

#include <cstdint>
#include <cstddef>
#include <bitset>

/* ------------------------------------------------------------------ */
/* Basic types shared by the live FIB, the image exporter and loader.  */
/* ------------------------------------------------------------------ */

typedef uint64_t nexthop_t;
static constexpr nexthop_t LPM_INVALID_NH = static_cast<nexthop_t>(-1);

struct ip6_t {
    uint64_t hi;
    uint64_t lo;
};

#ifndef RAM_NUM
#define RAM_NUM 11
#endif

typedef unsigned __int128 u128_t;

/* 22 bit forwarding values: 4194303 is the "no fallback" marker. */
static constexpr uint32_t SCAMP_BMP_NULL = 4194303u;
static constexpr uint32_t SCAMP_HOP_MAX  = 4194302u;

static constexpr int      SCAMP_STAGES       = 11;
static constexpr int      SCAMP_STAGE_MAX    = 10;
static constexpr int      SCAMP_ABSENT_STAGE = 15;
static constexpr uint32_t SCAMP_CHILD_ABSENT = static_cast<uint32_t>(SCAMP_ABSENT_STAGE) << 6;

static constexpr uint32_t SCAMP_CELL_LIMIT   = 131072u;   /* cells per stage      */
static constexpr uint32_t SCAMP_ROW_LIMIT    = 65536u;    /* rows over all stages */
static constexpr uint32_t SCAMP_PREFIX_LIMIT = 8192u;     /* distinct prefixes    */
static constexpr uint32_t SCAMP_FRONT_LIMIT  = 4096u;     /* front entries        */
static constexpr uint32_t SCAMP_BITMAP_LIMIT = 8193u;     /* NI dictionary        */
static constexpr uint32_t SCAMP_NI_LIMIT     = 8192u;     /* NI entries           */

enum ScampNodeType : int {
    NODE_NONE = 0,
    TYPE1 = 1,  /* NI bitmap + 0..2 children, one cell   */
    TYPE2,      /* NI bitmap + 3..6 children, two cells  */
    TYPE3,      /* NI bitmap + 3 direct + bulk, 2 cells  */
    TYPE4,      /* one inline prefix, one cell           */
    TYPE5       /* two inline prefixes, two cells        */
};

/* One normalized FIB prefix: addr has all host bits cleared. */
struct ScampPrefix {
    u128_t   addr;
    uint8_t  len;
    uint32_t hop;
};

/* ------------------------------------------------------------------ */
/* 128 bit helpers (addresses are handled MSB first).                  */
/* ------------------------------------------------------------------ */

inline u128_t scamp_make128(uint64_t hi, uint64_t lo) {
    return (static_cast<u128_t>(hi) << 64) | static_cast<u128_t>(lo);
}
inline uint64_t scamp_hi(u128_t v) { return static_cast<uint64_t>(v >> 64); }
inline uint64_t scamp_lo(u128_t v) { return static_cast<uint64_t>(v); }

/* clear everything below the top `len` bits */
inline u128_t scamp_mask(u128_t v, int len) {
    if (len <= 0) return 0;
    if (len >= 128) return v;
    return v & ~((static_cast<u128_t>(1) << (128 - len)) - 1);
}

/* `cnt` bits starting at bit offset `off` (MSB first), zero padded on the right */
inline uint32_t scamp_bits(u128_t v, int off, int cnt) {
    if (cnt <= 0) return 0;
    if (off >= 128) return 0;
    u128_t m = (cnt >= 128) ? ~static_cast<u128_t>(0) : ((static_cast<u128_t>(1) << cnt) - 1);
    int shift = 128 - off - cnt;
    if (shift >= 0) return static_cast<uint32_t>((v >> shift) & m);
    return static_cast<uint32_t>((v << (-shift)) & m);
}

/* owner forest of a prefix length */
inline int scamp_origin(int len) {
    if (len <= 16) return 0;
    if (len <= 64) return 16;
    return 64;
}
inline int scamp_origin_max(int origin) {
    if (origin == 0) return 16;
    if (origin == 16) return 64;
    return 128;
}
/* front key of a prefix inside its owner forest */
inline uint64_t scamp_front_key(u128_t addr, int origin) {
    if (origin == 16) return scamp_bits(addr, 0, 16);
    if (origin == 64) return scamp_hi(addr);
    return 0;
}
/* logical (record) size of a node type, in 128 bit cells */
inline int scamp_type_cells(int type) { return (type == TYPE1 || type == TYPE4) ? 1 : 2; }

inline uint32_t scamp_popcount64(uint64_t v) {
    return static_cast<uint32_t>(__builtin_popcountll(v));
}

#endif /* SCAMPTRIE_BASE_H */
#ifndef SCAMP_IMAGE_PACK_H
#define SCAMP_IMAGE_PACK_H

#include "scamptrie_base.h"
#include <bitset>
#include <cstdint>

/* ------------------------------------------------------------------ */
/* Packed record layout.  Offsets are relative to the first bit of the */
/* record (bit 0 of a row for full records, bit 128 for a half record  */
/* living in the upper cell of a row).  bit0 is the integer LSB.       */
/* ------------------------------------------------------------------ */

/* common header */
static constexpr int PK_TYPE_OFF = 0,  PK_TYPE_BITS = 3;
static constexpr int PK_BMP_OFF  = 3,  PK_BMP_BITS  = 22;
/* TYPE1/2/3 */
static constexpr int PK_BID_OFF  = 25, PK_BID_BITS  = 16;   /* NI dictionary id */
static constexpr int PK_NIB_OFF  = 41, PK_NIB_BITS  = 22;   /* NI array base    */
static constexpr int PK_T1_CHILD = 63;                      /* 2 x child32      */
static constexpr int PK_T2_CHILD = 63;                      /* 6 x child32      */
/* TYPE3 */
static constexpr int PK_BULK_BM_OFF   = 63,  PK_BULK_BM_BITS   = 64;
static constexpr int PK_BULK_BASE_OFF = 127, PK_BULK_BASE_BITS = 22;
static constexpr int PK_BULK_STG_OFF  = 149, PK_BULK_STG_BITS  = 4;
static constexpr int PK_T3_DIRECT     = 153;                /* 3 x child32      */
static constexpr int PK_T3_RSVD_OFF   = 249, PK_T3_RSVD_BITS   = 7;
/* TYPE4 / TYPE5 inline prefixes */
static constexpr int PK_INL0_OFF      = 25;
static constexpr int PK_INL1_OFF      = 119;
static constexpr int PK_INL_BITS      = 94;
static constexpr int PK_INL_FRAG_BITS = 64;
static constexpr int PK_INL_LEN_BITS  = 8;
static constexpr int PK_INL_HOP_BITS  = 22;
static constexpr int PK_T4_RSVD_OFF   = 119, PK_T4_RSVD_BITS   = 9;
static constexpr int PK_T5_RSVD_OFF   = 213, PK_T5_RSVD_BITS   = 43;
/* reserved bit of TYPE1 / TYPE2 */
static constexpr int PK_T1_RSVD_OFF   = 127;
static constexpr int PK_T2_RSVD_OFF   = 255;
/* child32 sub fields, LSB first */
static constexpr int PK_CH_KEY_BITS   = 6;
static constexpr int PK_CH_STAGE_BITS = 4;
static constexpr int PK_CH_CELL_BITS  = 22;

typedef std::bitset<256> Row256;

/* write `n` bits of `v` (LSB first) at `pos`, advancing `pos` */
inline void pk_write(Row256& row, int& pos, uint64_t v, int n) {
    for (int i = 0; i < n; ++i) row[pos++] = ((v >> i) & 1u) != 0;
}
/* read `n` bits (LSB first) at `pos` */
inline uint64_t pk_read(const Row256& row, int pos, int n) {
    uint64_t v = 0;
    for (int i = 0; i < n; ++i) if (row[pos + i]) v |= (1ULL << i);
    return v;
}
/* are all `n` bits at `pos` zero? */
inline bool pk_zero(const Row256& row, int pos, int n) {
    for (int i = 0; i < n; ++i) if (row[pos + i]) return false;
    return true;
}
inline uint32_t pk_child_value(int key, int stage, uint32_t cell) {
    if (stage == SCAMP_ABSENT_STAGE) return SCAMP_CHILD_ABSENT;
    return (static_cast<uint32_t>(key) & 0x3Fu) |
           ((static_cast<uint32_t>(stage) & 0xFu) << 6) |
           ((cell & 0x3FFFFFu) << 10);
}

#endif /* SCAMP_IMAGE_PACK_H */
#ifndef SCAMP_FIB_H
#define SCAMP_FIB_H

#include "scamptrie_base.h"
#include <vector>

/* Live forwarding table: a plain binary trie over the 128 address bits.
   Puts are last-write-wins, lookups are exact longest-prefix matches and
   the same structure answers bounded lookups used for image BMP fields. */
class LiveFib {
public:
    LiveFib() { nodes_.push_back(Node()); }

    void put(u128_t addr, int len, uint32_t hop);
    nexthop_t lookup(u128_t addr) const { return lookup_bounded(addr, 128); }
    nexthop_t lookup_bounded(u128_t addr, int maxlen) const;
    void enumerate(std::vector<ScampPrefix>& out) const;
    size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    struct Node {
        int32_t ch[2];
        uint32_t hop;
        Node() { ch[0] = ch[1] = -1; hop = SCAMP_BMP_NULL; }
    };
    std::vector<Node> nodes_;
    size_t count_ = 0;

    void walk(int idx, int depth, u128_t acc, std::vector<ScampPrefix>& out) const;
};

#endif /* SCAMP_FIB_H */
#ifndef SCAMP_IMAGE_BUILD_H
#define SCAMP_IMAGE_BUILD_H

#include "image.hpp"
#include <vector>

/* Build a detached, compact image of a complete FIB.
   `prefixes` must hold distinct normalized prefixes (host bits cleared). */
ImageData build_image(const std::vector<ScampPrefix>& prefixes);
